SELECT CASE WHEN last_error IS NULL OR last_error = '' THEN 0 ELSE 1 END
FROM video_status_outbox
WHERE event_id = #{eventId}

SELECT process_status
FROM video_status_consumed_event
WHERE event_id = #{eventId}

SELECT TIMESTAMPDIFF(SECOND, created_at, NOW(3))
FROM video_status_outbox
WHERE event_id = #{eventId}
